function planRow(item={}){const row=document.createElement('div');row.className='plan-exercise-row';const match=item.exerciseId||(data.exercises||[]).find(e=>e.name===item.name)?.id||'';row.innerHTML=`<div class="field exercise-select"><label>Exercício *</label><select class="plan-exercise" required><option value="">Selecione da biblioteca</option>${(data.exercises||[]).map(e=>`<option value="${esc(e.id)}" ${e.id===match?'selected':''}>${esc(e.name)} · ${esc(e.group||'')}</option>`).join('')}</select></div><label>Séries<input class="plan-sets" type="number" min="1" step="1" inputmode="numeric" value="${esc(item.sets??3)}" required></label><label>Repetições<input class="plan-reps" type="text" value="${esc(item.reps??'8–12')}" placeholder="Ex.: 8–12" required></label><label>Carga (kg)<input class="plan-load" type="number" min="0" step="any" inputmode="decimal" value="${esc(item.loadKg??item.kg??'')}"></label><label>Descanso (s)<input class="plan-rest" type="number" min="0" step="1" inputmode="numeric" value="${esc(item.rest??90)}"></label><div class="plan-row-actions"><button type="button" class="btn secondary small move-up" aria-label="Mover exercício para cima">↑</button><button type="button" class="btn secondary small move-down" aria-label="Mover exercício para baixo">↓</button><button type="button" class="btn danger small remove-plan-exercise">Remover</button></div>`;row.querySelector('.remove-plan-exercise').onclick=()=>{row.remove();if(!$('#plan-exercises').children.length)$('#plan-exercises').append(planRow())};row.querySelector('.move-up').onclick=()=>{const prev=row.previousElementSibling;if(prev)row.parentNode.insertBefore(row,prev)};row.querySelector('.move-down').onclick=()=>{const next=row.nextElementSibling;if(next)row.parentNode.insertBefore(next,row)};return row}
function planForm(x={}){const editing=!!x.id;modalFrame(editing?'Editar ficha de treino':'Nova ficha de treino',`<form id="plan-form"><div class="field-grid"><div class="field"><label>Nome da ficha *</label><input name="name" required maxlength="120" value="${esc(x.name||'')}"></div><div class="field"><label>Observações</label><input name="notes" value="${esc(x.notes||'')}"></div></div><div class="section-head"><h3>Exercícios e parâmetros individuais</h3><button type="button" class="btn secondary small" id="plan-add-exercise">＋ Adicionar exercício</button></div><p class="source-note">Cada exercício tem suas próprias séries, repetições, carga inicial e descanso. Arraste a ordem com as setas.</p><div id="plan-exercises" class="editor-list"></div><div class="form-actions"><button type="button" class="btn secondary" data-close>Cancelar</button><button type="submit" class="btn">Salvar ficha</button></div></form>`);$('#modal-root').querySelector('[data-close]').onclick=closeModal;const list=$('#plan-exercises');(x.exercises?.length?x.exercises:[{}]).forEach(e=>list.append(planRow(e)));$('#plan-add-exercise').onclick=()=>list.append(planRow());$('#plan-form').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,v=Object.fromEntries(new FormData(form));const rows=[...list.querySelectorAll('.plan-exercise-row')];const exercises=rows.map(row=>{const exercise=(data.exercises||[]).find(z=>z.id===row.querySelector('.plan-exercise').value);return exercise?{exerciseId:exercise.id,name:exercise.name,sets:Math.max(1,Math.floor(NV.num(row.querySelector('.plan-sets').value))),reps:row.querySelector('.plan-reps').value.trim(),loadKg:NV.num(row.querySelector('.plan-load').value),rest:NV.num(row.querySelector('.plan-rest').value)}:null});if(!exercises.length||exercises.some(e=>!e)||rows.some(row=>!row.querySelector('.plan-reps').value.trim())){NV.toast('Selecione um exercício da biblioteca e preencha os parâmetros de cada item.');return}try{await NVDB.put('plans',{...x,id:x.id||NV.id(),name:v.name.trim(),notes:v.notes.trim(),exercises});closeModal();await refresh();render();NV.toast('Ficha salva com sucesso.')}catch(err){NV.toast(err.message||'Não foi possível salvar a ficha.')}}}
function lastExerciseSession(exerciseId,excludeId=''){return exerciseHistory(exerciseId,excludeId)[0]||null}
function workoutSetRow(set={}){const row=document.createElement('div');row.className='workout-set-row';row.innerHTML=`<span class="set-number"></span><label>Carga (kg)<input class="session-set-load" type="number" min="0" step="any" inputmode="decimal" value="${esc(set.kg??'')}"></label><label>Repetições<input class="session-set-reps" type="number" min="0" step="1" inputmode="numeric" value="${esc(set.reps??'')}"></label><label class="set-done"><input type="checkbox" class="session-set-done" ${set.completed?'checked':''}> Concluída</label><button type="button" class="btn danger small remove-session-set">×</button>`;row.querySelector('.remove-session-set').onclick=()=>{const parent=row.parentElement;row.remove();renumberSets(parent)};return row}
