function editProfile(){let p=profile();let f=[field('sex','Sexo','select',{options:options(['masculino','feminino'])}),field('birth','Data de nascimento','date'),field('height','Altura (cm)','number',{min:1,step:'any'}),field('weight','Peso atual (kg)','number',{min:1,step:'any'}),field('activity','Nível de atividade','select',{options:options(Object.keys(NV.activity))}),field('goal','Objetivo','select',{options:options(['perder','manter','ganhar'])}),field('pace','Ritmo desejado (kg/semana)','number',{min:0,step:'any'}) ,...Object.keys(NV.metas).map(k=>field('target_'+k,(NV.labels[k]||k)+' — meta diária','number',{min:0,step:'any'}))];let obj={...p};Object.keys(NV.metas).forEach(k=>obj['target_'+k]=p.targets?.[k]??(k==='calories'?NVProfile.goal(p):k==='water'?NVProfile.water(p):NV.metas[k]));openForm('Perfil e metas',f,obj,async v=>{const targets={};Object.keys(NV.metas).forEach(k=>targets[k]=NV.num(v['target_'+k]));await NVDB.put('profile',{...p,...v,id:'profile',targets})})}
function add(store){if(store==='profile')return editProfile();formFor(store,{})}
async function remove(store,id){if(!confirm('Excluir este registro? Esta ação não pode ser desfeita.'))return;await NVDB.remove(store,id);await refresh();render();NV.toast('Registro excluído.')}
function bind(){document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>edit(b.dataset.edit,b.dataset.id));document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>remove(b.dataset.delete,b.dataset.id));document.querySelectorAll('[data-goto]').forEach(b=>b.onclick=()=>{page=b.dataset.goto;render()});document.querySelectorAll('[data-start-plan]').forEach(b=>b.onclick=()=>startWorkout(b.dataset.startPlan));const progressSelect=$('#progress-exercise');if(progressSelect)progressSelect.onchange=()=>{progressExerciseId=progressSelect.value;render()};document.querySelectorAll('[data-quick-water]').forEach(b=>b.onclick=()=>quickWater(+b.dataset.quickWater));document.querySelectorAll('[data-day-shift]').forEach(b=>b.onclick=()=>{const d=new Date(day+'T12:00:00');d.setDate(d.getDate()+Number(b.dataset.dayShift));day=d.toISOString().slice(0,10);render()});const di=$('#diary-date');if(di)di.onchange=()=>{day=di.value||NV.today();render()};const search=$('#food-search');if(search)search.oninput=()=>{foodFilter=search.value;const list=(data.foods||[]).filter(x=>x.name.toLowerCase().includes(foodFilter.toLowerCase()));$('#food-list').innerHTML=itemList('foods',list,x=>`${esc(x.category||'Sem categoria')} · ${NV.fmt(x.calories)} kcal / 100 g · P ${NV.fmt(x.protein,1)} g`);bind()};const cat=$('#food-category');if(cat)cat.onchange=()=>{let c=cat.value,list=(data.foods||[]).filter(x=>(!foodFilter||x.name.toLowerCase().includes(foodFilter.toLowerCase()))&&(!c||x.category===c));$('#food-list').innerHTML=itemList('foods',list,x=>`${esc(x.category||'')} · ${NV.fmt(x.calories)} kcal / 100 g`);bind()};const preset=$('#report-preset');if(preset)preset.onchange=()=>{if(preset.value!=='custom'){const r=reportRange(preset.value);reportFilter={preset:preset.value,...r}}else{reportFilter={preset:'custom',start:$('#report-start').value,end:$('#report-end').value}}render()};const rs=$('#report-start'),re=$('#report-end');if(rs)rs.onchange=()=>{reportFilter={preset:'custom',start:rs.value,end:re.value};if(reportFilter.start&&reportFilter.end&&reportFilter.start>reportFilter.end){reportFilter.end=reportFilter.start;NV.toast('A data final foi ajustada para não anteceder a inicial.')}render()};if(re)re.onchange=()=>{reportFilter={preset:'custom',start:rs.value,end:re.value};if(reportFilter.start&&reportFilter.end&&reportFilter.end<reportFilter.start){reportFilter.start=reportFilter.end;NV.toast('A data inicial foi ajustada para não ultrapassar a final.')}render()};document.querySelectorAll('[data-favorite]').forEach(b=>b.onclick=async()=>{let f=getById('foods',b.dataset.favorite);await NVDB.put('foods',{...f,favorite:!f.favorite});await refresh();render()})}
async function quickWater(ml){await NVDB.put('water',{id:NV.id(),date:day,ml});await refresh();render();NV.toast(`${ml} ml registrados.`)}
async function action(a){switch(a){case'add-entry':add('entries');break;case'quick-entry':openForm('Lançamento rápido',[field('name','Descrição','text',{required:true}),field('meal','Refeição','select',{options:options(NVDiary.meals)}),...['calories','protein','carbs','fat'].map(k=>field(k,NV.labels[k],'number',{min:0,step:'any'}))],{meal:'Almoço'},async v=>{await NVDB.put('entries',{...v,id:NV.id(),date:day,...Object.fromEntries(['calories','protein','carbs','fat'].map(k=>[k,NV.num(v[k])]))})});break;case'add-food':add('foods');break;case'add-recipe':add('recipes');break;case'add-exercise':add('exercises');break;case'add-plan':add('plans');break;case'add-activity':add('activities');break;case'add-cardio':add('cardio');break;case'add-water':add('water');break;case'add-weight':add('weights');break;case'add-measure':add('measures');break;case'add-note':let n=(data.notes||[]).find(x=>x.date===day);formFor('notes',n||{date:day});break;case'edit-profile':editProfile();break;case'backup':await NVBackup.export();NV.toast('Backup exportado.');break;case'restore':restore();break;case'theme':toggleTheme();break;case'erase-all':if(confirm('Apagar TODOS os dados salvos neste aparelho? Esta ação não pode ser desfeita.')){await NVDB.clear();await NVDB.put('settings',{id:'seed-control',skipSeed:true});data={};await refresh();render();NV.toast('Todos os dados locais foram apagados.')}break;case'copy-day':await copyDay();break;case'food-template':downloadTemplate();break;case'food-import':foodImport();break;case'export-csv':exportCSV();break;case'start-workout':startWorkout();break;case'fast-start':localStorage.setItem('nvFastStart',Date.now());render();break;case'fast-stop':localStorage.removeItem('nvFastStart');NV.toast('Temporizador de jejum encerrado.');render();break}}
async function copyDay(){let prev=new Date(day+'T12:00:00');prev.setDate(prev.getDate()-1);let date=prev.toISOString().slice(0,10),items=(data.entries||[]).filter(x=>x.date===date);if(!items.length){NV.toast('Não há lançamentos no dia anterior.');return}for(const e of items)await NVDB.put('entries',{...e,id:NV.id(),date:day});await refresh();render();NV.toast('Lançamentos copiados para o dia selecionado.')}
function toggleTheme(){let light=!document.body.classList.contains('light');document.body.classList.toggle('light',light);localStorage.setItem('nvTheme',light?'light':'dark')}
function restore(){let i=document.createElement('input');i.type='file';i.accept='.json,application/json';i.onchange=async()=>{try{await NVBackup.import(i.files[0]);await refresh();render();NV.toast('Backup restaurado.')}catch(e){alert(e.message)}};i.click()}
function downloadTemplate(){let blob=new Blob(['nome,categoria,porcao,calorias,proteina,carboidratos,gorduras,fibras,sodio\nFeijão caseiro,Leguminosas,100,76,4.8,13.6,0.5,8.5,2\n'],{type:'text/csv;charset=utf-8'});download(blob,'modelo-alimentos.csv')}
function foodImport(){let i=document.createElement('input');i.type='file';i.accept='.csv,.json,application/json,text/csv';i.onchange=async()=>{try{const text=await i.files[0].text();let rows;if(i.files[0].name.endsWith('.json')){let parsed=JSON.parse(text);rows=Array.isArray(parsed)?parsed:parsed.foods}else{const lines=text.trim().split(/\r?\n/).slice(1);rows=lines.map(l=>{let c=l.split(',');return {name:c[0],category:c[1],serving:+c[2]||100,calories:+c[3]||0,protein:+c[4]||0,carbs:+c[5]||0,fat:+c[6]||0,fiber:+c[7]||0,sodium:+c[8]||0}})}if(!Array.isArray(rows)||!rows.length)throw Error('Nenhum alimento encontrado no arquivo.');for(const x of rows)await NVDB.put('foods',{...Object.fromEntries(NV.nutrients.map(k=>[k,NV.num(x[k])])),...x,id:x.id||NV.id(),serving:x.serving||100,source:'Importado pelo usuário'});await refresh();render();NV.toast(`${rows.length} alimentos importados.`)}catch(e){alert('Falha ao importar: '+e.message)}};i.click()}
function download(blob,name){let a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function exportCSV(){let entries=data.entries||[];if(page==='reports'){const r=reportRange();entries=entries.filter(e=>e.date>=r.start&&e.date<=r.end)}let rows=[['data','refeicao','alimento','kcal','proteinas_g','carboidratos_g','gorduras_g','fibras_g','sodio_mg'],...entries.map(e=>[e.date,e.meal,e.name,e.calories,e.protein,e.carbs,e.fat,e.fiber,e.sodium])];download(new Blob(['\ufeff'+rows.map(r=>r.map(v=>`"${String(v??'').replaceAll('"','""')}"`).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'}),`nutrivida-diario-${NV.today()}.csv`)}
function drawCharts(){document.querySelectorAll('canvas.chart').forEach(c=>{let pts=JSON.parse(c.dataset.points||'[]'),ctx=c.getContext('2d'),w=c.clientWidth,h=210,dpr=devicePixelRatio||1;c.width=w*dpr;c.height=h*dpr;ctx.scale(dpr,dpr);ctx.clearRect(0,0,w,h);if(!pts.length)return;let vals=pts.map(p=>Number(p.value)||0),max=Math.max(1,...vals),pad=28,barW=Math.max(5,(w-pad*2)/pts.length*.55);ctx.strokeStyle=getComputedStyle(document.body).getPropertyValue('--line');ctx.fillStyle=getComputedStyle(document.body).getPropertyValue('--muted');ctx.font='10px system-ui';for(let j=0;j<4;j++){let y=pad+(h-pad*2)*j/3;ctx.beginPath();ctx.moveTo(pad,y);ctx.lineTo(w-8,y);ctx.stroke()}pts.forEach((p,i)=>{let x=pad+(w-pad*2)*(i+.5)/pts.length,bh=(h-pad*2)*vals[i]/max;ctx.fillStyle=getComputedStyle(document.body).getPropertyValue('--accent');ctx.fillRect(x-barW/2,h-pad-bh,barW,bh);ctx.fillStyle=getComputedStyle(document.body).getPropertyValue('--muted');ctx.textAlign='center';ctx.fillText(p.label,x,h-6)})})}
