async function init(){try{await NVDB.open()}catch(e){$('#view').innerHTML='<div class="empty">O armazenamento local IndexedDB não está disponível neste navegador. Abra em um navegador atualizado.</div>';return}const seedGuard=(await NVDB.all('settings')).some(x=>x.id==='seed-control'&&x.skipSeed);if(!seedGuard){if(!(await NVDB.all('foods')).length)await seed();if(!(await NVDB.all('activities')).length){for(const a of NVCardio.activities)await NVDB.put('activities',{...a,id:'seed-activity-'+a.name})}}await refresh();const theme=localStorage.getItem('nvTheme');if(theme==='light')document.body.classList.add('light');$('#quick-theme').onclick=toggleTheme;$('#mobile-menu').onclick=()=>{page='home';render()};document.addEventListener('click',e=>{if(e.target.matches('[data-action="theme"]'))toggleTheme()});if('serviceWorker'in navigator&&/^https?:$/.test(location.protocol))navigator.serviceWorker.register('./service-worker.js').catch(()=>{});render()}
